INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65008210', 65008210, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Bidang Penyelenggaraan Sekolah Unggul', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99960000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Bidang Penyelenggaraan Sekolah Unggul memiliki keluaran berupa Laporan Akhir Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Bidang Penyelenggaraan Sekolah Unggul dengan waktu penyelesaian dibagi dalam 6 termin pembayaran (11 Bulan), rincian sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan Data Dukung Mekanisme Sinergi MRPN dalam Pengendalian dan Evaluasi Bidang Penyelenggaraan Sekolah Unggul 2 Termin 2 Laporan Analisis MRPN Bidang Penyelenggaraan Sekolah Unggul dalam Evaluasi TW I 3 Termin 3 Laporan Hasil Crosscheck Risiko dan Mitigasi TW I Bidang Penyelenggaraan Sekolah Unggul 4 Termin 4 Laporan Analisis MRPN Bidang Penyelenggaraam Sekolah Unggul untuk Pengendalian TW II 5 Termin 5 Laporan Penyiapan Analisis Manajemen Risiko TW III Bidang Penyelenggaraan Sekolah Unggul 6 Termin 6 Laporan Akhir Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Pembangunan Bidang Penyelenggaraan Sekolah Unggul', 'Lingkup kegiatan dan tanggung jawab untuk Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Pengendalian dan Evaluasi Berbasis Manajemen Risiko Bidang Penyelenggaraan Sekolah Unggul adalah sebagai berikut: 1. Menyusun mekanisme sinergi dan integrasi MRPN dengan pengendalian dan evaluasi program prioritas presiden bidang Penyelenggaraan Sekolah Unggul; 2. Menyusun analisis MRPN pada bidang Penyelenggaraan Sekolah Unggul sebagai bahan pendukung pengendalian dan evaluasi program prioritas presiden; 3. Melakukan identifikasi, analisis, validasi, dan mitigasi berdasarkan data pelaporan; 4. Menyusun laporan hasil analisis MRPN dan merumuskan usulan intervensi pengendalian pembangunan pada periode selanjutnya; 5. Melakukan review atas risiko pembangunan serta menyusun usulan rekomendasi kebijakan berbasis risiko untuk mendukung pencapaian sasaran program prioritas presiden bidang Penyelenggaraan Sekolah Unggul.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1891052);
