INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64989778', 64989778, 'analyze_legacy', 'Provinsi Sumatera Utara', 'provinsi', 'Dinas Pendidikan', 'Jasa Konsultansi Pengawasan Pembangunan Ruang UKS SMKN 1 Gunung Sitoli Utara', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Sumatera Utara, Gunung Sitoli (Kota)', 15000000, 'February 2026', 'APBD', 1, 1, '1 paket', 'Jasa Konsultansi Pengawasan Pembangunan Ruang UKS SMKN 1 Gunung Sitoli Utara', 'macam pekerjaan yang dilaksanakan oleh Konsultan Pengawas adalah: (1) Penyedia jasa pengawasan konstruksi mulai bertugas sejak ditetapkan berdasarkan SPMK sampai dengan paling lambat 2 (dua) minggu setelah serah terima akhir pekerjaan oleh penyedia jasa pelaksanaan konstruksi yaitu: a. memeriksa dan mempelajari dokumen untuk pelaksanaan konstruksi yang akan dijadikan dasar dalam pengawasan pekerjaan di lapangan. b. mengawasi pemakaian bahan, peralatan dan metode pelaksanaan, serta mengawasi ketepatan waktu, dan biaya pekerjaan konstruksi. c. mengawasi pelaksanaan konstruksi dari segi kualitas, kuantitas, dan laju pencapaian volume atau realisasi fisik. d. mengumpulkan data dan informasi di lapangan untuk memecahkan persoalan yang terjadi selama pelaksanaan konstruksi. e. menyelenggarakan rapat-rapat lapangan secara berkala, membuat laporan mingguan dan bulanan pekerjaan pengawasan, dengan masukan hasil rapat-rapat lapangan, laporan harian, mingguan dan bulanan pekerjaan konstruksi yang dibuat oleh penyedia jasa pelaksanaan konstruksi. f. meneliti gambar-gambar untuk pelaksanaan (shop drawing) yang diajukan oleh penyedia jasa pelaksanaan konstruksi. g. meneliti gambar-gambar yang sesuai dengan pelaksanaan di lapangan (As Built Drawing) sebelum serah terima pertama. h. menyusun daftar cacat atau kerusakan sebelum serah terima pertama, mengawasi perbaikannya pada masa pemeliharaan, dan menyusun laporan akhir pekerjaan pengawasan. i. menyusun berita acara persetujuan kemajuan pekerjaan, berita acara pemeliharaan pekerjaan, dan serah terima pertama dan akhir pelaksanaan konstruksi sebagai kelengkapan untuk pembayaran angsuran pekerjaan konstruksi. j. bersama-sama penyedia jasa perencanaan konstruksi menyusun petunjuk pemeliharaan dan penggunaan bangunan gedung. k. membantu pengelola kegiatan dalam menyusun Dokumen Pendaftaran. l. melakukan pemeriksaan dan menyatakan kelaikan fungsi bangunan gedung terbangun sesuai dengan IMB. m. membantu pengelola kegiatan dalam penyiapan kelengkapan dokumen Sertifikat Laik Fungsi (SLF) dari Pemerintah Kabupaten atau Kota setempat. (2) Penyedia jasa pengawasan konstruksi dalam melaksanakan tugasnya bertanggung jawab secara kontraktual kepada Pejabat Penandatangan Kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1894750);
