INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65032823', 65032823, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Manajemen Risiko Pembangunan Nasional sebagai Instrumen Pengendalian dan Evaluasi Pembangunan Bidang Energi', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 89700000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Lingkup kegiatan dan tanggung jawab untuk Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Manajemen Risiko Pembangunan Nasional sebagai Instrumen Pengendalian dan Evaluasi Pembangunan Bidang Energi adalah sebagai berikut: 1. Menyusun mekanisme sinergi dan integrasi MRPN dengan pengendalian dan evaluasi program prioritas presiden bidang energi; 2. Menyusun analisis MRPN pada bidang energi sebagai bahan pendukung pengendalian dan evaluasi program prioritas presiden; 3. Melakukan identifikasi, analisis, validasi, dan mitigasi berdasarkan data pelaporan; 4. Menyusun laporan hasil analisis MRPN dan merumuskan usulan intervensi pengendalian pembangunan bidang energi pada periode selanjutnya; 5. Melakukan review atas risiko pembangunan serta menyusun usulan rekomendasi kebijakan berbasis risiko untuk mendukung pencapaian sasaran program prioritas presiden bidang energi;', 'Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Manajemen Risiko Pembangunan Nasional sebagai Instrumen Pengendalian dan Evaluasi Pembangunan Bidang Energi memiliki keluaran berupa Laporan Akhir Optimalisasi Manajemen Risiko Pembangunan Nasional sebagai Instrumen Pengendalian dan Evaluasi Pembangunan Bidang Energi dengan waktu penyelesaian dibagi dalam 6 termin, rincian sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan pengembangan metodologi sinergi MRPN dalam pengendalian dan evaluasi Bidang Energi 2 Termin 2 Laporan Analisis MRPN Bidang Energi Dalam Evaluasi Ex-Ante 3 Termin 3 Laporan Analisis MRPN Bidang Energi untuk Pengendalian TW I 4 Termin 4 Laporan Analisis MRPN Bidang Energi untuk Pengendalian TW II 5 Termin 5 Laporan Analisis MRPN Bidang Energi untuk Pengendalian TW III 6 Termin 6 Laporan Akhir Optimalisasi Manajemen Risiko Pembangunan Nasional sebagai Instrumen Pengendalian dan Evaluasi Pembangunan Bidang Energi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1895314);
